"""Structured captions: (title, one-line summary, body). Order: data -> scales/axes -> symbols -> references. No instructions to the reader."""
from nea_captions import *
H = lambda t: f'<b>{t}</b> '
P = lambda *a: ''.join(f'<p>{x}</p>' for x in a if x)
SYM = (H('SYMBOLS.') + f'💥 potentially hazardous asteroid (PHA), 🪨 other near-Earth asteroid (NEA), ☄️ comet, 🥔 main-belt asteroid. A {PHA} is larger than about 140 m and can pass within about 19.5 lunar distances of Earth’s orbit.')
SIZE_KM = H('SIZE.') + 'Circle colour shows the size class: blue, 1–10 m; green, 10–100 m; yellow, 100 m–1 km; pink, over 1 km. Sizes are estimated from each object’s absolute magnitude (' + SIZEEST + ').'
REFS = lambda extra='': H('REFERENCES.') + f'{LDDEF}. Large and small numbers use scientific notation: 1.9E<sup>7</sup> means 1.9 × 10<sup>7</sup>. Axis limits are recalculated at every refresh.{extra}'
D15 = H('DATA.') + f'The 15 near-Earth asteroids that pass closest to Earth in the next 7 days, from the {MPCNEO} and the {SBDB}. The page refreshes automatically every 8 hours. Distances come from {CA}; the data was obtained using the {NEOWS}.'
def parts(fn):
    if fn.startswith('1-3'):
        log = fn.startswith(('1-3-', '1-3c'))
        sc = ('Both axes are logarithmic, so equal steps mean equal ratios, which keeps the nearest and the farthest objects readable together.' if log else 'Both axes are linear and start at zero.')
        box = ' The dotted box explains the symbols and sizes, and the arrows point from it to the list of objects and to the size legend.' if fn.startswith(('1-3c', '1-3d')) else ''
        return ('Distance vs velocity and size · ' + ('logarithmic' if log else 'linear'), 'Distance, speed and size of the 15 near-Earth asteroids passing closest to Earth in the next 7 days.',
            P(D15, H('SCALES.') + 'The bottom axis is the distance from Earth in lunar distances (LD); the top axis shows the same distances in kilometres. The left axis is the speed relative to Earth in km/s. ' + sc + ' The boxed list on the right ranks the objects from fastest to slowest and its numbers match the circles.' + box, SYM + ' ' + 'Circle area follows the object’s mean size. ' + SIZE_KM, REFS()))
    if fn.startswith('2-3'):
        grid = ' Faint dotted grid lines help to read the values.' if 'grid' in fn else ''
        sw = 'swapped' in fn
        return ('Size, distance and velocity' + (' · axes swapped' if sw else '') + (' · with grid' if grid else ''), 'Size, distance and speed of the 15 closest near-Earth asteroids drawn in one three-dimensional frame.',
            P(D15, H('SCALES.') + 'Horizontal: object size in km, from zero. Depth: distance in LD and km, from 1 LD (a distance cannot be negative). Vertical: speed relative to Earth in km/s, from zero. A light dotted line drops from each object to the floor, and another runs from the distance axis to its place in depth.' + grid + ' The distance values are turned a quarter-turn beside the axis, whose name runs parallel to it. The list on the right ranks the objects by speed.', H('HOW THE THREE VALUES RELATE.') + 'A distance can never be negative. Distance in km = LD × 384,400. The time an object needs to cover that distance at its relative speed v is t = d / v (for example, 20 LD = 7.7 million km at 15 km/s takes about 6 days). Its apparent angular size from Earth is about θ ≈ D / d, where D is its diameter. For a density ρ, its mass is m = (π/6) ρ D³ and its kinetic energy is E = ½ m v², so energy grows with the cube of the size and the square of the speed.', SYM, SIZE_KM, REFS(), ('In this version the two axes are swapped: lunar distance (LD on the left, km on the right) is the vertical axis and the relative velocity runs in depth along the bottom edge.' if sw else '')))
    if fn.startswith('3'):
        log = not fn.startswith('3b')
        return ('Diameter vs distance · ' + ('logarithmic' if log else 'linear'), 'Size range and distance of the 15 closest near-Earth asteroids passing in the next 7 days.',
            P(D15, H('SCALES.') + 'Each horizontal line spans the smallest to the largest size estimate for one object; the symbol marks the mean and the end bars [ | ] mark the extremes. Bottom axis: diameter in km. Left axis: distance in LD; right axis: the same distance in km. ' + ('All three axes are logarithmic.' if log else 'All axes are linear and start at zero.'), SYM, H('SIZE.') + 'Sizes are estimated from each object’s absolute magnitude (' + SIZEEST + ').', REFS()))
    if fn.startswith(('07-', '08-')):
        log = fn.startswith('07-')
        return ('Cumulative NEAs since first capture · ' + ('logarithmic' if log else 'linear'), 'Running total of distinct near-Earth asteroids seen since 1 November 2026, and how many of them are potentially hazardous.',
            P(H('DATA.') + f'Each new object is counted on its close-approach date, using the {MPCNEO} and the {SBDB}. The chart is redrawn automatically every 8 hours. Last updated: {UPD}. The data was obtained using the {NEOWS}.', H('SCALES.') + 'The horizontal axis is the date; the vertical axis is the cumulative count' + (', drawn logarithmically so early growth stays visible.' if log else ' on a linear scale.'), H('SYMBOLS.') + f'🪨 all NEAs; 💥 the {PHA}s.'))
    if fn.startswith('imp1'):
        return ('Impact risk · distance vs Torino and Palermo scales', 'The Sentry objects with the highest impact risk, placed by closest-approach distance and by their Torino and Palermo scale values.',
            P(H('DATA.') + f'JPL’s {SENTRY} risk table (top 15 by Palermo value) and {CA}, refreshed automatically every 8 hours. Only objects with a known close-approach distance are drawn.', H('SCALES.') + f'Bottom axis: distance in LD (top axis in km), both logarithmic. Left axis: the {TORINO} (0–10), which combines impact probability and consequences for the public; 0 means no hazard. Right axis: the {PALERMO}, which compares the risk with the background risk; below −2 is no cause for concern. Each object’s symbol sits at its Palermo value and a dotted line joins it to its Torino value.', H('SYMBOLS.') + '⚠️ the three highest impact probabilities; the numbers are the Palermo rank (1 = highest). 💥 PHA, 🪨 NEA, ☄️ comet, 🥔 main-belt asteroid. ' + SIZE_KM, REFS()))
    if fn.startswith('imp3b'):
        return ('Impact risk · alert level and timeline by century', 'The century timeline of the Sentry list, with a live alert in the title that follows the most critical object in the next 200 years.',
            P(H('THE CENTURY TIMELINE OF THE SENTRY LIST.') + f'The title follows the most critical object in JPL’s {SENTRY} feed within <b>the next 200 years</b> (highest Torino and cumulative Palermo value). Only objects that pass the thresholds within those two centuries trigger the alert, and the alert and those objects flash at the same rate. There are four alert tiers:',
              '<span style="color:#ff6961">▲</span> Tier 4 · <b><i>“Lets see what happens!”</i></b> (Torino 8 or more, or Palermo 2.0 or more) · flashes every 1.2 s<br><span style="color:#ffb6c1">▲</span> Tier 3 · <b><i>“Time for everyone to look up!”</i></b> (Torino 5–7, or Palermo 0.0–1.99) · 1.3 s<br><span style="color:#fdfd96">▲</span> Tier 2 · <b><i>“We are checking stuff out”</i></b> (Torino 2–4, or Palermo −2.0 to −0.01) · 1.5 s<br><span style="color:#77dd77">▲</span> Tier 1 · <b><i>“All Good, we keep looking up!”</i></b> (Torino 0–1 and Palermo below −2.0) · 1.7 s',
              H('HOW THE IMPACT PROBABILITY IS CALCULATED.') + f'An object’s orbit is fitted to its observations, but measurements are never exact, so {SENTRY} studies a whole cloud of orbits that all fit the data. The impact probability p<sub>i</sub> is the share of that cloud whose orbits hit Earth on the date shown. The {PALERMO} (PS) compares it with the background risk: <b>PS = log<sub>10</sub>( p<sub>i</sub> / (f<sub>B</sub> × T) )</b>. Here p<sub>i</sub> is the impact probability (a number between 0 and 1, no units); T is the years until the possible impact; E is the impact energy in megatons (one megaton is the energy of one million tonnes of TNT, about 4.2 × 10<sup>15</sup> joules); and f<sub>B</sub> = 0.03 × E<sup>−0.8</sup> is the yearly chance, per year, of an impact at least that energetic. Example: for p<sub>i</sub> = 1E<sup>−4</sup>, T = 50 years and E = 10 Mt, f<sub>B</sub> = 0.03 × 10<sup>−0.8</sup> ≈ 0.0048 per year; f<sub>B</sub> × T ≈ 0.24; p<sub>i</sub> / 0.24 ≈ 4.2E<sup>−4</sup>; PS = log<sub>10</sub>(4.2E<sup>−4</sup>) ≈ −3.4. Below −2 is no cause for concern; 0 means as likely as the background. The {TORINO} (0–10) combines probability and energy for the public (read {SENTRY_INTRO}).',
              H('PLOTTED ICONS.') + 'Height is the impact probability (logarithmic) and each column is a century. Circle size and colour show diameter: blue, 1–10 m; green, 10–100 m; yellow, 100 m–1 km; pink, over 1 km. ⚠️ marks the three highest probabilities; the numbers are the Palermo rank. 💥 potentially hazardous asteroid (PHA), 🪨 near-Earth asteroid (NEA), ☄️ comet, 🥔 main-belt asteroid. A PHA is larger than about 140 m and can pass within about 19.5 LD of Earth’s orbit. Large and small numbers use scientific notation: 1.9E<sup>7</sup> means 1.9 × 10<sup>7</sup>. Axis limits are recalculated at every refresh.',
              H('DATA.') + f'{A("https://cneos.jpl.nasa.gov/sentry/", "JPL Sentry risk table")} (top 15 by Palermo value) and {CA}, refreshed automatically every 8 hours. The Sentry table gives no error bars for impact probability, so none are drawn.'))
    if fn.startswith('imp3'):
        return ('Impact risk · timeline by century', 'The Sentry objects on a century timeline, by impact probability and size.',
            P(H('DATA.') + f'JPL’s {SENTRY} risk table (top 15 by Palermo value), refreshed automatically every 8 hours.', H('SCALES.') + 'Each column is a century; empty centuries are skipped. Height is the impact probability on a logarithmic scale.', H('SYMBOLS.') + '⚠️ the three highest probabilities (numbers are the Palermo rank), 💥 PHA, 🪨 NEA, ☄️ comet, 🥔 main-belt asteroid. ' + SIZE_KM, REFS()))
    return (fn, '', '')
